		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Ingrese el numero de partidos que el equipo deportivo gano en el torneo: ");
			wins = scan.nextInt();
		}
		//Paso 4: Leer el numero de partidos que el equipo deportivo empato en el torneo
		System.out.println("Ingrese el numero de empates: ");
		int ties = scan.nextInt();		
		//Paso 5: Validar la entrada del usuario para el numero de empates; pedir una entrada valida mientras el usuario introduzca un numero invalido; de lo contrario detenerse
		while ( ties < 0 || totalGames < (ties + wins) ) {
			System.out.println("Ingrese el numero de empates: ");
			ties = scan.nextInt();
